import { version } from '../analytics-version';
import TrialPanel from 'devextreme/core/trial_panel';
const { showTrialPanel, registerTrialPanelComponents } = TrialPanel;
registerTrialPanelComponents();
export function _addLicenseTrigger(licenseOptions) {
    if (licenseOptions && !licenseOptions.isLicensed) {
        showTrialPanel(licenseOptions.buyNowLink, licenseOptions.licensingDocLink, licenseOptions.version || version, licenseOptions.subscriptions);
    }
}
